using Ohno.CircleGame.Gameplay;
namespace Ohno.QA13;
public static partial class Tests
{
    static void Records()
    {
        Add("I/fresh-alias","E042 M0ace:0001/0006; M32de",()=>{using var f=Flow();Yes(ReferenceEquals(f.HandlerRecord,f.GlobalRecord),"handler/global alias");Eq(f.SelectedRecord,null);Eq(f.Finalized,false);});
        Add("I/complete-flags-not-score","M0acd F1978/F197c; M2b5a F1990",()=>{var r=new Record{Numeric=1234,Max=2};r.Prepare(3);r.Complete(false,11);Eq(r.Score,1234);Eq(r.N300,(ushort)10);Eq(r.Success,true);Eq(r.Valid,false);Eq(r.Perfect,false);Eq(r.Grade(),RankGrade.X);});
        Add("I/global-replacement-before-selector","M0acd handler vs M2285 global",()=>{var h=new Record();using var f=Flow(h);Finish(f);var g=new Record{Identity=h.Identity,Success=false,C300=0,Miss=10};f.GlobalRecord=g;Eq(f.RequestRank(),TransitionDecision.Accepted);Eq(f.SelectorGrade,RankGrade.F);Eq(f.Transitions.Pending,RankMode.SelectPlay);Eq(h.Success,true);Eq(g.Valid,false);});
        Add("I/replacement-during-cleanup","M46b0 cleanup before M32db/M32de",()=>{var h=new Record();using var f=Flow(h);Finish(f);f.RequestRank();var replacement=new Record{Identity=h.Identity,Numeric=811,Success=true,C300=7,C100=3};f.Commit(()=>f.GlobalRecord=replacement);Eq(f.SelectedRecord,null);f.Initialize(200);Yes(ReferenceEquals(f.SelectedRecord,replacement),"selection after cleanup");Yes(ReferenceEquals(f.HandlerRecord,h),"handler retained");Eq(f.Presentation!.Score,"00000811");Eq(f.Presentation.Grade.First,RankGrade.C);});
        Add("I/synchronous-success-mutation","M2267:02fb / M32de record retention",()=>{var r=new Record();using var f=Flow(r);Finish(f);f.RequestRank();Eq(f.SelectorGrade,RankGrade.X);f.Commit(()=>r.Success=false);f.Initialize(0);Eq(f.SelectedRecord!.Grade(),RankGrade.F);Eq(f.Presentation!.Grade.First,RankGrade.F);});
        Add("I/deferred-cleanup-live-vs-captured","E042 M46df old-object capture; engineering capture",()=>{var r=new Record{Numeric=19};using var f=Flow(r);Finish(f);f.RequestRank();Action deferred=()=>{r.Success=false;r.Numeric=991;r.C300=1;r.Miss=9;};f.Commit(()=>{});f.Initialize(0);var p=f.Presentation!;deferred();Eq(p.Score,"00000019");Eq(p.N300,(ushort)10);Eq(p.Grade.First,RankGrade.X);Eq(f.SelectedRecord!.Score,991);Eq(f.SelectedRecord.Grade(),RankGrade.F);});
        Add("I/map-mismatch","M32db map resolution boundary; engineering rejection",()=>{using var f=Flow();Finish(f);f.RequestRank();f.Commit(()=>f.GlobalRecord=new Record{Success=true});Eq(f.Initialize(0),false);Eq(f.Stage,RankStage.Unavailable);Eq(f.Presentation,null);});
        Add("I/null-at-initialization","E042 R43; engineering missing global boundary",()=>{using var f=Flow();Finish(f);f.RequestRank();f.Commit(()=>f.GlobalRecord=null);Eq(f.Initialize(0),false);Eq(f.SelectedRecord,null);Eq(f.Stage,RankStage.Unavailable);});
        Add("I/null-at-selector","M2285 global dependency; bounded null rejection",()=>{using var f=Flow();Finish(f);f.GlobalRecord=null;Eq(f.RequestRank(),TransitionDecision.Rejected);Eq(f.Stage,RankStage.Unavailable);Eq(f.Transitions.Pending,null);});
        Add("I/live-session-ledger","M2b4b/M2b42/M32d7 original getter boundaries",()=>{var m=Map();var s=CircleSession.CreateFreshOrdinary(m,ScoreConfiguration.FromBeatmap(m));var r=new SessionRankRecord(s);Yes(ReferenceEquals(r.Session,s),"actual session retained");Yes(ReferenceEquals(r.MapIdentity,m),"actual map retained");Eq(r.Score,0);s.Press(new(256,192),2000);Eq(r.Score,s.Ledger.Score);Eq(r.N300,(ushort)1);Eq(r.MaximumCombo,s.Ledger.MaximumCombo);Eq(r.AccuracyFraction,s.Ledger.AccuracyFraction);r.Complete(false,1);Eq(r.Grade(),RankGrade.X);Yes(!ReferenceEquals(r.SessionIdentity,r.MapIdentity),"session and map identities distinct");});
        foreach(var (prepared,max,expected) in new (int,int,bool)[]{(10,10,true),(10,9,false),(10,11,true),(int.MinValue,1,false),(int.MaxValue,-1,true)})
            Add($"I/perfect-{prepared}-{max}","M0acd:003d signed unchecked prepared-minus-max",()=>{var r=new Record{Max=max,C300=9,Miss=1};r.Prepare(prepared);r.Complete(false,10);Eq(r.Perfect,(bool?)expected);Eq(r.Success,true);Eq(r.Grade(),RankGrade.B);});
        Add("I/perfect-unavailable","E035 completed trial provenance required",()=>{var m=Map();var s=CircleSession.CreateFreshOrdinary(m,ScoreConfiguration.FromBeatmap(m),false);var r=new SessionRankRecord(s);r.Complete(false,1);Eq(r.PreparedCombo,null);Eq(r.Perfect,null);Eq(r.UnsupportedReason,null);});
        foreach(var (subset,schedule) in new[]{(0,1),(0,5),(1,4),(2,9)})Add($"I/combo-order-{subset}-{schedule}","E035 M1150:02a8/03db; E042 F05fd",()=>{var c=new HealthChart(0,1200,14,[new(1000,1500,ScoreObjectKind.Slider,true,subset,schedule),new(2000,2000,ScoreObjectKind.Circle,false),new(3000,4000,ScoreObjectKind.Spinner,false,SpinnerRequirement:99)],[]);Eq(RankAdmission.PreparedCombo(c),schedule+3);});
        Add("I/invalid-preparation-rejected","E035 HealthChart validation boundary",()=>{var c=new HealthChart(0,1200,14,[new(1000,1500,ScoreObjectKind.Slider,true,5,2)],[]);Throws<InvalidDataException>(()=>RankAdmission.PreparedCombo(c));});
        Add("I/failure-not-accuracy","M0acd success NOT failed",()=>{var r=new Record();r.Complete(true,10);Eq(r.AccuracyFraction,1f);Eq(r.Success,false);Eq(r.Grade(),RankGrade.F);Eq(r.Valid,true);});
        Add("I/missed-result-can-perfect","F197c separate from F1978 and accuracy",()=>{var r=new Record{C300=9,Miss=1,Max=12};r.Prepare(12);r.Complete(false,10);Eq(r.Perfect,true);Yes(r.AccuracyFraction<1f,"perfect not accuracy100");});
    }
    static void Policies()
    {
        Add("P/fresh-ordinary-admitted","E023 ordinary base factory; E042 scoped domain",()=>{var m=Map();var s=CircleSession.CreateFreshOrdinary(m,ScoreConfiguration.FromBeatmap(m));Eq(RankAdmission.Check(m,s.Ledger,new()),null);});
        var policies=new Dictionary<string,RankPolicyInputs>{["mode"]=new(Ruleset:1),["mods"]=new(Modifiers:8),["notfresh"]=new(FreshCreation:false),["recorded"]=new(RecordedInput:true),["source"]=new(SourceRecord:true),["restored"]=new(Restored:true),["alternate"]=new(AlternateRecord:true),["accumulator"]=new(Accumulator:true)};
        foreach(var (name,policy) in policies)Add("P/reject-"+name,"E023 record factory; explicit R15 admission",()=>{var m=Map();var ledger=new ScoreLedger(ScoreConfiguration.FromBeatmap(m));Yes(RankAdmission.Check(m,ledger,policy)!=null,"unsupported "+name);Eq(ledger.Score,0);Eq(ledger.EventCount,0);});
        foreach(int count in new[]{6999,7000,7001})Add("P/row-count-"+count,"E023 M2234 automatic ScoreV2 at >=7000",()=>{string rows=string.Join('\n',Enumerable.Range(0,count).Select(i=>$"256,192,{2000+i*10},1,0,0:0:0:0:"));var m=Map(rows);var ledger=new ScoreLedger(ScoreConfiguration.EngineeringPractice);Eq(m.ScoreMetadata!.RowCount,count);Eq(RankAdmission.Check(m,ledger,new()) is null,count<7000);Eq(ledger.EventCount,0);});
        Add("P/clone-rejected","E036 exact parser ownership / E042 record provenance",()=>{var m=Map();var clone=m with{};Yes(RankAdmission.Check(clone,new(ScoreConfiguration.FromBeatmap(m)),new())!=null,"clone not fresh");});
        Add("P/ScoreV2-rejected","E023 non-base policy distinct",()=>{var m=Map();var ledger=new ScoreLedger(new(1,ScorePolicy.ScoreV2,"explicit artificial"));Yes(RankAdmission.Check(m,ledger,new())!=null,"ScoreV2 unsupported");Eq(ledger.Score,0);});
        Add("P/missing-score-metadata","E034 chart multiplier provenance",()=>{var m=Map() with{ScoreMetadata=null};Yes(RankAdmission.Check(m,new(ScoreConfiguration.EngineeringPractice),new())!=null,"missing metadata");});
        Add("P/optional-display-fields","E042 M32db header vs supported optional fields",()=>{var m=Map(metadata:"Title:Only title");var s=CircleSession.CreateFreshOrdinary(m,ScoreConfiguration.FromBeatmap(m));var r=new SessionRankRecord(s);Eq(r.UnsupportedReason,null);Eq(r.Metadata.Title,"Only title");Yes(string.IsNullOrEmpty(r.Metadata.Difficulty),"no fabricated difficulty");Yes(string.IsNullOrEmpty(r.Metadata.Artist),"no fabricated artist");});
    }
}
